export const MONUMENTS = JSON.parse("[{\"id\":\"n8695170074\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. А. Браудо\",\"x\":-3618.4,\"z\":427.8,\"subject\":\"Q4096092\",\"inscription\":\"В этом доме с 1928 по 1970 год жил выдающийся органист, педагог Исай Александрович Браудо\"},{\"id\":\"n14015790868\",\"kind\":\"artwork\",\"sub\":\"mural\",\"x\":-3668.5,\"z\":432.5},{\"id\":\"n4349646989\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Похищение Прозерпины Плутоном\",\"x\":-4576,\"z\":375},{\"id\":\"n6549729288\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. П. Герману\",\"x\":-4545.2,\"z\":290.8,\"subject\":\"Q18168757\",\"inscription\":\"Здесь с 1903 по 1953 гг. жил и работал выдающийся учёный, один из создателей советской школы горной механики академик Александр Петрович Герман\"},{\"id\":\"n6549729289\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Б. И. Бокию\",\"x\":-4546.9,\"z\":298.2,\"subject\":\"Q12083722\",\"inscription\":\"Здесь с 1907 по 1927 гг. жил и работал один из основоположников горной науки профессор Борис Иванович Бокий\"},{\"id\":\"n6549729290\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. П. Карпинскому\",\"x\":-4548.7,\"z\":305.8,\"subject\":\"Q729563\",\"inscription\":\"Здесь учился, жил и работал с 1858 по 1896 год выдающийся геолог и палеонтолог, профессор Горного института, создатель отечественной геологической школы, первый президент советской Академии наук, академик Александр Петрович Карпинский\"},{\"id\":\"n6549729291\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Скочинскому\",\"x\":-4549.5,\"z\":309.6,\"subject\":\"Q4422470\",\"inscription\":\"Здесь с 1895 по 1930 гг. учился и работал крупнейший учёный, основоположник рудничной аэрологии академик Александр Александрович Скочинский\"},{\"id\":\"n6549729292\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. С. Курнакову\",\"x\":-4551.3,\"z\":317.2,\"subject\":\"Q4248622\",\"inscription\":\"Здесь с 1882 по 1941 гг. жил и работал выдающийся советский химик академик Николай Семёнович Курнаков\"},{\"id\":\"n6549729293\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Е. С. Фёдорову\",\"x\":-4552.1,\"z\":320.9,\"subject\":\"Q726827\",\"inscription\":\"Здесь с 1896 по 1919 гг. жил и работал гениальный русский учёный, основоположник современной науки о кристаллах академик Евграф Степанович Фёдоров\"},{\"id\":\"n8866305311\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"2-й Гвардейской дивизии Народного ополчения\",\"x\":-4571.5,\"z\":238.4,\"inscription\":\"В этом здании с 30 июня по 5 августа 1041 года формировалась 2-я Гвардейская дивизия Народного ополчения, участвовавшая в обороне Ленинграда\"},{\"id\":\"n4349628892\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Геркулес, удушающий Антея\",\"x\":-4554,\"z\":344.4},{\"id\":\"n6491682682\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. Н. Кузнецову\",\"x\":-4590,\"z\":205.7,\"subject\":\"Q28358774\",\"inscription\":\"Здесь с 1900 по 1946 гг. жил и работал лауреат Государственной премии, заслуженный деятель науки и техники профессор Александр Назарович Кузнецов\"}]");
